import { addDays, parseISO } from '../solver/dateUtils';
import type { ISODate } from '../solver/types';

/*
 * Time blocks (COVERAGE-SPEC §3). A block is a half-open UTC interval labelled with the
 * site's LOCAL date and start minute. Blocks are generated by walking real UTC instants
 * from local midnight to the next local midnight, so:
 *   - DST spring-forward: the missing local hour simply has no blocks (a 23-hour day);
 *   - DST fall-back: the repeated local hour appears twice, the second time with fold 1
 *     (a 25-hour day). Demand templates keyed on local time apply to both.
 * Pure: uses Intl for time zone offsets, no Date-dependent globals beyond that.
 */

export const DEFAULT_BLOCK_MINUTES = 30;
const MIN = 60_000;

export interface Block {
  /** `2026-03-08T01:30`, with `b` appended for the second pass through a repeated local time. */
  key: string;
  date: ISODate;
  /** Local minutes after midnight at the block start (0–1439). */
  startMinute: number;
  utcStart: number;
  utcEnd: number;
  /** 1 for the second occurrence of a local time on a fall-back day. */
  fold: 0 | 1;
}

export interface Interval {
  start: number;
  end: number;
}

const fmtCache = new Map<string, Intl.DateTimeFormat>();
function fmt(tz: string): Intl.DateTimeFormat {
  let f = fmtCache.get(tz);
  if (!f) {
    f = new Intl.DateTimeFormat('en-US', {
      timeZone: tz,
      hourCycle: 'h23',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    });
    fmtCache.set(tz, f);
  }
  return f;
}

/** Local wall-clock date and minute-of-day for a UTC instant. */
export function localParts(utcMs: number, tz: string): { date: ISODate; minute: number } {
  const parts: Record<string, string> = {};
  for (const p of fmt(tz).formatToParts(new Date(utcMs))) parts[p.type] = p.value;
  return { date: `${parts.year}-${parts.month}-${parts.day}`, minute: Number(parts.hour) * 60 + Number(parts.minute) };
}

/** Offset (local − UTC) in minutes at a UTC instant. */
export function offsetMinutes(utcMs: number, tz: string): number {
  const { date, minute } = localParts(utcMs, tz);
  const { y, m, d } = parseISO(date);
  const asUtc = Date.UTC(y, m - 1, d) + minute * MIN;
  return Math.round((asUtc - Math.floor(utcMs / MIN) * MIN) / MIN);
}

/**
 * The UTC instant of a local wall time. A time that does not exist (spring-forward gap)
 * maps to the same offset as just before the gap, i.e. it moves forward by the DST shift
 * (02:30 → 03:30); an ambiguous time (fall-back) maps to its first occurrence.
 */
export function zonedToUtc(date: ISODate, minute: number, tz: string): number {
  const { y, m, d } = parseISO(date);
  const naive = Date.UTC(y, m - 1, d) + minute * MIN;
  const o1 = offsetMinutes(naive - 12 * 60 * MIN, tz);
  const o2 = offsetMinutes(naive + 12 * 60 * MIN, tz);
  // Candidates under each offset seen around this day; prefer the earliest that round-trips.
  const cands = [...new Set([o1, o2])].map((o) => naive - o * MIN).sort((a, b) => a - b);
  for (const c of cands) {
    const lp = localParts(c, tz);
    if (lp.date === date && lp.minute === minute) return c;
  }
  // Inside a gap: use the offset in force before it.
  return naive - o1 * MIN;
}

/** All blocks of a local day in a time zone. */
export function blocksForDay(date: ISODate, tz: string, blockMinutes = DEFAULT_BLOCK_MINUTES): Block[] {
  const start = zonedToUtc(date, 0, tz);
  const end = zonedToUtc(addDays(date, 1), 0, tz);
  const out: Block[] = [];
  const seen = new Set<number>();
  for (let t = start; t < end; t += blockMinutes * MIN) {
    const lp = localParts(t, tz);
    const fold: 0 | 1 = seen.has(lp.minute) ? 1 : 0;
    seen.add(lp.minute);
    out.push({
      key: `${lp.date}T${hhmm(lp.minute)}${fold ? 'b' : ''}`,
      date: lp.date,
      startMinute: lp.minute,
      utcStart: t,
      utcEnd: Math.min(t + blockMinutes * MIN, end),
      fold,
    });
  }
  return out;
}

/**
 * A shift or absence given in local times on a date. `endMinute ≤ startMinute` means the
 * interval ends on the next day (crosses midnight). `endMinute = 1440` is midnight.
 */
export function localInterval(date: ISODate, startMinute: number, endMinute: number, tz: string): Interval {
  const start = zonedToUtc(date, startMinute, tz);
  const nextDay = endMinute >= 1440 || endMinute <= startMinute;
  const end = zonedToUtc(nextDay ? addDays(date, 1) : date, endMinute >= 1440 ? endMinute - 1440 : endMinute, tz);
  return { start, end };
}

/** Part-day leave on a date mapped to an interval (SPEC §6: am = until noon, pm = from noon). */
export function leaveInterval(
  date: ISODate,
  part: 'full' | 'am' | 'pm' | 'hours',
  tz: string,
  hours?: { startMinute: number; endMinute: number } | null,
): Interval {
  switch (part) {
    case 'full':
      return localInterval(date, 0, 1440, tz);
    case 'am':
      return localInterval(date, 0, 720, tz);
    case 'pm':
      return localInterval(date, 720, 1440, tz);
    case 'hours':
      if (!hours) return localInterval(date, 0, 1440, tz);
      return localInterval(date, hours.startMinute, hours.endMinute, tz);
  }
}

export const overlaps = (a: Interval, b: Interval): boolean => a.start < b.end && b.start < a.end;
export const covers = (outer: Interval, inner: Interval): boolean => outer.start <= inner.start && outer.end >= inner.end;
export const blockInterval = (b: Block): Interval => ({ start: b.utcStart, end: b.utcEnd });
export const hoursIn = (i: Interval): number => (i.end - i.start) / 3_600_000;

export function hhmm(minute: number): string {
  return `${String(Math.floor(minute / 60)).padStart(2, '0')}:${String(minute % 60).padStart(2, '0')}`;
}

/** "14:30" → 870. */
export function parseHhmm(s: string): number {
  const m = /^(\d{1,2}):(\d{2})$/.exec(s.trim());
  if (!m) throw new Error(`Not a time: ${s}`);
  const h = Number(m[1]);
  const mm = Number(m[2]);
  if (h > 24 || mm > 59 || (h === 24 && mm > 0)) throw new Error(`Not a time: ${s}`);
  return h * 60 + mm;
}
